const key='baladatrade-trades-v1';
let trades=JSON.parse(localStorage.getItem(key)||'[]');
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const money=n=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(n);
const number=(n,d=2)=>new Intl.NumberFormat('pt-BR',{maximumFractionDigits:d}).format(n);
async function checkSession(){const data=await fetch('/api/auth/session').then(r=>r.json()).catch(()=>({authenticated:false}));$('#authWall').classList.toggle('hidden',data.authenticated);if(data.authenticated)brokerStatus()}
$('#loginForm').onsubmit=async e=>{e.preventDefault();$('#loginError').textContent='Entrando…';const response=await fetch('/api/auth/login',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({password:$('#loginPassword').value})});const data=await response.json();if(!response.ok){$('#loginError').textContent=data.error||'Falha no login';return}$('#loginError').textContent='';$('#loginPassword').value='';$('#authWall').classList.add('hidden');brokerStatus()};
$('#logout').onclick=async()=>{await fetch('/api/auth/logout',{method:'POST'});$('#authWall').classList.remove('hidden')};
const missions=[
 {icon:'◎',title:'Primeiro plano',desc:'Registre uma operação com risco e plano definidos.',test:t=>t.some(x=>x.planned),xp:40},
 {icon:'◈',title:'Processo consistente',desc:'Registre três operações respeitando suas regras.',test:t=>t.filter(x=>x.planned).length>=3,xp:80},
 {icon:'◇',title:'Risco sob controle',desc:'Mantenha todos os registros com risco informado.',test:t=>t.length>=3&&t.every(x=>x.risk>0),xp:60},
 {icon:'↙',title:'Aceitou a perda',desc:'Documente uma perda sem quebrar o plano.',test:t=>t.some(x=>x.pnl<0&&x.planned),xp:50},
 {icon:'✓',title:'Revisão completa',desc:'Adicione notas de aprendizado em cinco operações.',test:t=>t.filter(x=>x.notes.length>10).length>=5,xp:100},
 {icon:'☼',title:'Semana consciente',desc:'Registre trades em três datas diferentes.',test:t=>new Set(t.map(x=>x.date)).size>=3,xp:120}
];
function stats(){const net=trades.reduce((a,t)=>a+t.pnl,0),wins=trades.filter(t=>t.pnl>0),loss=Math.abs(trades.filter(t=>t.pnl<0).reduce((a,t)=>a+t.pnl,0)),gross=wins.reduce((a,t)=>a+t.pnl,0),disc=trades.length?trades.filter(t=>t.planned).length/trades.length*100:0,done=missions.filter(m=>m.test(trades)),xp=trades.reduce((a,t)=>a+(t.planned?20:5)+(t.notes.length>10?5:0),0)+done.reduce((a,m)=>a+m.xp,0);return{net,wins,loss,gross,disc,done,xp,level:Math.floor(xp/100)+1}}
function render(){const s=stats();$('#net').textContent=money(s.net);$('#net').className=s.net<0?'negative':'positive';$('#netHint').textContent=trades.length?'Resultado dos registros':'Nenhum trade registrado';$('#winRate').textContent=trades.length?`${(s.wins.length/trades.length*100).toFixed(0)}%`:'0%';$('#tradeCount').textContent=`${trades.length} operações`;$('#profitFactor').textContent=s.loss?(s.gross/s.loss).toFixed(2):s.gross?'∞':'—';$('#discipline').textContent=`${s.disc.toFixed(0)}%`;$('#score').textContent=Math.round(s.disc);$('#xp').textContent=s.xp;$('#level').textContent=$('#levelRing').textContent=s.level;$('#xpBar').style.width=`${s.xp%100}%`;$('#nextLevel').textContent=`${100-s.xp%100} XP para o nível ${s.level+1}`;$('#streakSide').textContent=new Set(trades.filter(t=>t.planned).map(t=>t.date)).size;renderTrades();renderMissions(s);drawChart()}
function renderTrades(){const sorted=[...trades].sort((a,b)=>b.date.localeCompare(a.date));$('#recentTrades').innerHTML=sorted.slice(0,4).map(t=>`<div class="trade-row"><div><b>${esc(t.asset)} · ${esc(t.side)}</b><small>${t.date} · ${esc(t.market)}${t.planned?' · plano respeitado':''}</small></div><strong class="${t.pnl>=0?'positive':'negative'}">${money(t.pnl)}</strong></div>`).join('')||'<div class="empty">Nenhuma operação ainda.</div>';$('#tradeTable').innerHTML=sorted.map(t=>`<tr><td>${t.date}</td><td><b>${esc(t.asset)}</b></td><td>${esc(t.market)}</td><td>${esc(t.side)}</td><td class="${t.pnl>=0?'positive':'negative'}">${money(t.pnl)}</td><td>${money(t.risk)}</td><td>${t.planned?'✓ Sim':'— Não'}</td><td><button class="delete" data-id="${t.id}">Excluir</button></td></tr>`).join('');$('#emptyTable').style.display=trades.length?'none':'block';$$('.delete').forEach(b=>b.onclick=()=>{trades=trades.filter(t=>t.id!==b.dataset.id);save()})}
function renderMissions(s){const card=m=>`<article class="panel mission ${m.test(trades)?'done':''}"><span class="icon">${m.icon}</span><h3>${m.title}</h3><p class="muted">${m.desc}</p><span class="tag">${m.test(trades)?'CONCLUÍDA':`+${m.xp} XP`}</span></article>`;$('#missionGrid').innerHTML=missions.map(card).join('');$('#missionPreview').innerHTML=missions.slice(0,3).map(m=>`<div class="mission-row"><div><b>${m.title}</b><small>${m.desc}</small></div><span class="tag">${m.test(trades)?'✓':`+${m.xp}`}</span></div>`).join('');$('#missionCount').textContent=`${missions.slice(0,3).filter(m=>m.test(trades)).length}/3`}
function drawChart(){const c=$('#equity'),ctx=c.getContext('2d'),ordered=[...trades].sort((a,b)=>a.date.localeCompare(b.date));ctx.clearRect(0,0,c.width,c.height);$('#emptyChart').style.display=ordered.length?'none':'block';c.style.display=ordered.length?'block':'none';if(!ordered.length)return;let total=0,values=[0,...ordered.map(t=>total+=t.pnl)],min=Math.min(...values),max=Math.max(...values),range=max-min||1,pad=28,pts=values.map((v,i)=>[pad+i*(c.width-pad*2)/(values.length-1),(c.height-pad)-(v-min)/range*(c.height-pad*2)]);ctx.strokeStyle='#dce5df';ctx.beginPath();ctx.moveTo(pad,c.height-pad);ctx.lineTo(c.width-pad,c.height-pad);ctx.stroke();ctx.strokeStyle='#0b7a53';ctx.lineWidth=4;ctx.beginPath();pts.forEach((p,i)=>i?ctx.lineTo(...p):ctx.moveTo(...p));ctx.stroke();ctx.lineTo(pts.at(-1)[0],c.height-pad);ctx.lineTo(pad,c.height-pad);ctx.fillStyle='rgba(11,122,83,.09)';ctx.fill()}
function save(){localStorage.setItem(key,JSON.stringify(trades));render()}
function esc(v){const d=document.createElement('div');d.textContent=v;return d.innerHTML}
$$('.nav').forEach(b=>b.onclick=()=>show(b.dataset.view));$$('[data-go]').forEach(b=>b.onclick=()=>show(b.dataset.go));function show(id){$$('.view').forEach(v=>v.classList.toggle('active',v.id===id));$$('.nav').forEach(n=>n.classList.toggle('active',n.dataset.view===id));$('#viewTitle').textContent={dashboard:'Bom dia, holder.',holding:'Patrimônio Binance',radar:'Radar de mercado',markets:'Todos os mercados',paper:'Simulador Spot',expenses:'Gastos e resultado',journal:'Diário de trades',missions:'Missões de disciplina',risk:'Gestão de risco',broker:'Conexão Binance'}[id];if(id==='holding')loadPortfolioHistory();if(id==='paper')refreshPaper();if(id==='markets')loadMarkets()}
const modal=$('#tradeModal');$('#newTrade').onclick=()=>openModal();$$('.open-modal').forEach(b=>b.onclick=openModal);$$('.close').forEach(b=>b.onclick=()=>modal.close());function openModal(){const f=$('#tradeForm');f.reset();f.elements.date.value=new Date().toISOString().slice(0,10);modal.showModal()}
$('#tradeForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);trades.push({id:crypto.randomUUID(),asset:f.get('asset').toUpperCase(),market:f.get('market'),side:f.get('side'),pnl:Number(f.get('pnl')),risk:Number(f.get('risk')),date:f.get('date'),planned:f.get('planned')==='on',notes:f.get('notes')||''});save();modal.close();show('dashboard')};
$('#riskForm').onsubmit=e=>{e.preventDefault();const capital=Number($('#capital').value),pct=Number($('#riskPct').value),entry=Number($('#entry').value),stop=Number($('#stop').value),risk=capital*pct/100,distance=Math.abs(entry-stop);$('#maxRisk').textContent=money(risk);$('#positionSize').textContent=distance?`${Math.floor(risk/distance)} unidades`:'Stop inválido'};
async function brokerStatus(){try{const s=await fetch('/api/binance/status').then(r=>r.json());$('#brokerStatus').textContent=s.configured?`Conectada em ${s.environment}`:'Aguardando chaves';$('#brokerDetail').textContent=`Trading real: ${s.liveEnabled?'habilitado':'bloqueado'} · limite: ${s.maxOrderNotional} USDT` }catch{$('#brokerStatus').textContent='Servidor indisponível'}}
async function refreshHolding(){const button=$('#refreshHolding');button.disabled=true;button.textContent='Consultando tudo…';try{const response=await fetch('/api/portfolio/refresh',{method:'POST'}),data=await response.json();if(!response.ok)throw new Error(data.error);$('#holdingTotal').textContent=`${number(data.total,4)} USDT`;$('#holdingChange').textContent=`${data.changePct>=0?'+':''}${number(data.changePct)}%`;$('#holdingChange').className=data.changePct>=0?'positive':'negative';$('#holdingChangeValue').textContent=`${data.changeValue>=0?'+':''}${number(data.changeValue,4)} USDT`;$('#holdingAssets').textContent=data.assets.length;$('#holdingTime').textContent=new Date(data.capturedAt).toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'});$('#holdingList').innerHTML=data.assets.map(a=>`<div class="holding-row"><div><b>${esc(a.asset)}</b><small>${number(a.quantity,8)} unidades · ${number(a.changePct)}% em 24h</small><div class="wallet-badges">${a.wallets.map(w=>`<i>${esc(w)}</i>`).join('')}</div></div><div><strong>${a.priced?`${number(a.value,4)} USDT`:'Sem cotação'}</strong><span>${a.priced&&data.total?`${number(a.value/data.total*100)}% · via ${esc(a.priceSource||'USD')}`:'ativo incluído'}</span></div></div>`).join('')||'<div class="empty">Nenhum saldo encontrado.</div>';$('#holdingAlerts').innerHTML=data.alerts.map(a=>`<div class="alert ${a.level}"><b>${esc(a.asset)}</b><span>${esc(a.message)}</span></div>`).join('')||'<div class="empty">Nenhum limite de alerta atingido.</div>';$('#walletWarnings').innerHTML=(data.walletWarnings||[]).map(x=>`<div class="alert warning"><b>Cobertura parcial</b><span>${esc(x)}</span></div>`).join('');$('#walletSummary').innerHTML=Object.entries(data.walletTotals||{}).map(([wallet,total])=>`<article><strong>${esc(wallet)}</strong><span>${number(total,4)} USDT</span></article>`).join('');await loadPortfolioHistory()}catch(error){$('#holdingList').innerHTML=`<div class="empty negative">${esc(error.message)}</div>`}finally{button.disabled=false;button.textContent='Atualizar tudo'}}
async function loadPortfolioHistory(){try{const response=await fetch('/api/portfolio/history?limit=90'),data=await response.json();if(!response.ok)throw new Error(data.error);drawPortfolioHistory(data.history||[])}catch{$('#historyEmpty').textContent='Histórico indisponível.'}}
function drawPortfolioHistory(rows){const c=$('#portfolioHistory'),ctx=c.getContext('2d'),ordered=[...rows].reverse(),values=ordered.map(x=>Number(x.total_usdt));ctx.clearRect(0,0,c.width,c.height);$('#historyEmpty').style.display=values.length>=2?'none':'block';c.style.display=values.length>=2?'block':'none';if(values.length<2)return;const min=Math.min(...values),max=Math.max(...values),range=max-min||1,pad=28,pts=values.map((v,i)=>[pad+i*(c.width-pad*2)/(values.length-1),(c.height-pad)-(v-min)/range*(c.height-pad*2)]),delta=values.at(-1)-values[0];$('#historyDelta').textContent=`${delta>=0?'+':''}${number(delta,4)} USDT`;$('#historyDelta').className=delta>=0?'positive':'negative';ctx.strokeStyle='#dce5df';ctx.beginPath();ctx.moveTo(pad,c.height-pad);ctx.lineTo(c.width-pad,c.height-pad);ctx.stroke();ctx.strokeStyle=delta>=0?'#0b7a53':'#d94b4b';ctx.lineWidth=4;ctx.beginPath();pts.forEach((p,i)=>i?ctx.lineTo(...p):ctx.moveTo(...p));ctx.stroke();ctx.lineTo(pts.at(-1)[0],c.height-pad);ctx.lineTo(pad,c.height-pad);ctx.fillStyle=delta>=0?'rgba(11,122,83,.09)':'rgba(217,75,75,.08)';ctx.fill()}
function renderMarketAlerts(alerts){$('#marketAlerts').innerHTML=alerts.slice(0,12).map(a=>`<div class="alert ${a.level}"><b>${esc(a.title)}</b><span>${esc(a.message)}</span></div>`).join('')||'<div class="empty">Nenhuma condição avançada detectada.</div>'}
let radarCoins=[];
function renderRadar(){const filter=$('#marginFilter')?.value||'all',coins=radarCoins.filter(c=>filter==='all'||filter==='10'&&c.isolatedMargin||filter==='5'&&c.crossMargin||filter==='spot'&&!c.crossMargin&&!c.isolatedMargin);$('#radarEmpty').style.display=coins.length?'none':'block';$('#radarEmpty').textContent=radarCoins.length?'Nenhum par corresponde ao filtro.':'Clique em Atualizar radar.';$('#radarTable').innerHTML=coins.map((c,i)=>`<tr><td>${i+1}</td><td><b>${esc(c.asset)}</b><small>${esc(c.symbol)}</small></td><td>${number(c.price,8)}</td><td class="${c.change24h>=0?'positive':'negative'}">${c.change24h>=0?'+':''}${number(c.change24h)}%</td><td>${number(c.volume,0)}</td><td>${number(c.low?(c.high-c.low)/c.low*100:0)}%</td><td>${c.high>c.low?number((c.price-c.low)/(c.high-c.low)*100,0):"—"}% ${c.high>c.low&&(c.price-c.low)/(c.high-c.low)>.9?"⚠ TOPO":""}</td><td>${c.isolatedMargin?'<span class="tag leverage-10">ATÉ 10x · ISOLADA</span>':c.crossMargin?'<span class="tag leverage-5">ATÉ 5x · CROSS</span>':'<span class="tag">SPOT</span>'}</td><td><b>${c.score}</b>/100</td><td><span class="tag">${esc(c.state)}</span></td></tr>`).join('')}
async function refreshRadar(){const button=$('#refreshRadar');button.disabled=true;button.textContent='Analisando…';try{const response=await fetch('/api/market/radar?limit=50'),data=await response.json();if(!response.ok)throw new Error(data.error);radarCoins=data.coins||[];renderMarketAlerts(data.alerts||[]);renderRadar()}catch(error){$('#radarEmpty').style.display='block';$('#radarEmpty').textContent=error.message}finally{button.disabled=false;button.textContent='Atualizar radar'}}
$('#marginFilter').onchange=renderRadar;
async function refreshPaper(){try{const response=await fetch('/api/paper/account'),data=await response.json();if(!response.ok)throw new Error(data.error);renderPaper(data)}catch(error){$('#paperResult').textContent=error.message}}
function renderPaper(data){const pnl=Math.abs(data.totalPnl)<.005?0:data.totalPnl;$('#paperEquity').textContent=`${number(data.equity,2)} USDT`;$('#paperCash').textContent=`${number(data.account.cash_usdt,2)} USDT`;$('#paperPnl').textContent=`${pnl>0?'+':''}${number(pnl,2)} USDT`;$('#paperPnl').className=pnl>=0?'positive':'negative';$('#paperCount').textContent=data.positions.length;$('#paperPositions').innerHTML=data.positions.map(p=>`<div class="paper-position"><b>${esc(p.asset)}</b><strong class="${p.pnl>=0?'positive':'negative'}">${p.pnl>=0?'+':''}${number(p.pnl,2)} USDT</strong><small>${number(p.quantity,8)} · médio ${number(p.average_price_usdt,6)} · atual ${number(p.price,6)} · ${p.pnlPct>=0?'+':''}${number(p.pnlPct)}%</small></div>`).join('')||'<div class="empty">Nenhuma posição simulada. Faça uma compra de treino ao lado.</div>';$('#paperOrders').innerHTML=data.orders.map(o=>`<tr><td>${new Date(o.created_at).toLocaleString('pt-BR')}</td><td>${esc(o.symbol)}</td><td>${o.side==='BUY'?'Compra':'Venda'}</td><td>${number(o.quantity,8)}</td><td>${number(o.price_usdt,6)}</td><td>${number(o.notional_usdt,2)} USDT</td></tr>`).join('');$('#paperOrdersEmpty').style.display=data.orders.length?'none':'block'}
async function analyzeMarket(){const button=$('#analyzeMarket'),result=$('#aiMarketResult');button.disabled=true;button.textContent='Claude analisando…';result.className='empty';result.textContent='Comparando força, volume e risco…';try{const response=await fetch('/api/ai/market-analysis',{method:'POST'}),data=await response.json();if(!response.ok)throw new Error(data.error);const a=data.analysis||{},assets=Array.isArray(a.assets)?a.assets:[],cautions=Array.isArray(a.cautions)?a.cautions:[];result.className='ai-result';result.innerHTML=`<p>${esc(a.summary||'Análise concluída.')}</p><div class="ai-assets">${assets.map(x=>`<div><span class="tag">${esc(x.label||'OBSERVAR')}</span><b>${esc(x.symbol||'')}</b><small>${esc(x.reason||'')}</small></div>`).join('')}</div>${cautions.length?`<ul>${cautions.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`:''}<small>${esc(data.disclaimer||'')}</small>`}catch(error){result.className='empty negative';result.textContent=error.message}finally{button.disabled=false;button.textContent='Analisar com Claude'}}
async function checkHotCoins(){if(!('Notification'in window)||Notification.permission!=='granted')return;try{const response=await fetch('/api/market/radar?limit=50'),data=await response.json();if(!response.ok)return;const now=Date.now(),cooldown=60*60*1000,last=JSON.parse(localStorage.getItem('baladatrade-alerts')||'{}');(data.alerts||[]).filter(a=>a.level==='info'||a.level==='danger').slice(0,4).forEach(a=>{if(now-(last[a.id]||0)<cooldown)return;new Notification(a.title,{body:`${a.message} Confirme antes de agir.`,icon:'/icon.svg'});last[a.id]=now});localStorage.setItem('baladatrade-alerts',JSON.stringify(last))}catch{}}
const alertButton=document.createElement('button');alertButton.id='enableAlerts';alertButton.className='secondary';alertButton.textContent=('Notification'in window&&Notification.permission==='granted')?'Alertas ativos':'Ativar alertas';$('#analyzeMarket').before(alertButton);alertButton.onclick=async()=>{if(!('Notification'in window))return alert('Este navegador não oferece notificações.');const permission=await Notification.requestPermission();alertButton.textContent=permission==='granted'?'Alertas ativos':'Alertas bloqueados';if(permission==='granted')checkHotCoins()};setInterval(()=>{if(!document.hidden)checkHotCoins()},5*60*1000);
$('#paperSide').onchange=()=>{$('#paperAmountLabel').firstChild.textContent=$('#paperSide').value==='BUY'?'Valor da compra (USDT)':'Quantidade da moeda'};
$('#paperForm').onsubmit=async e=>{e.preventDefault();const button=e.submitter;button.disabled=true;button.textContent='Simulando…';$('#paperResult').textContent='Consultando preço atual…';try{const response=await fetch('/api/paper/order',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({symbol:$('#paperSymbol').value,side:$('#paperSide').value,amount:Number($('#paperAmount').value)})}),data=await response.json();if(!response.ok)throw new Error(data.error);renderPaper(data.account);$('#paperResult').textContent=`Simulação executada a ${number(data.price,8)} USDT. Nenhum dinheiro real foi usado.`}catch(error){$('#paperResult').textContent=error.message}finally{button.disabled=false;updatePaperAction()}};
