$('#checkBroker').onclick=brokerStatus;$('#orderForm').onsubmit=async e=>{e.preventDefault();$('#orderResult').textContent='Validando…';const payload={symbol:$('#orderSymbol').value,side:$('#orderSide').value,quantity:Number($('#orderQty').value),price:Number($('#orderPrice').value)};const r=await fetch('/api/binance/order/test',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(payload)});const data=await r.json();$('#orderResult').textContent=data.ok?'Ordem aceita pela Testnet. Nenhum dinheiro real foi movimentado.':data.error};show('holding');checkSession();
let marketsLoaded=false;
const favoritesKey='baladatrade-market-favorites';
function favorites(){return JSON.parse(localStorage.getItem(favoritesKey)||'["SOLUSDT","BTCUSDT","ETHUSDT"]')}
async function loadMarkets(force=false){if(marketsLoaded&&!force){renderFavorites();return loadMarketChart()}$('#chartStatus').textContent='Carregando todos os pares…';try{const response=await fetch('/api/market/symbols'),data=await response.json();if(!response.ok)throw new Error(data.error);marketsLoaded=true;$('#marketCount').textContent=number(data.count,0);$('#binanceSymbols').innerHTML=data.symbols.map(x=>`<option value="${esc(x.symbol)}">${esc(x.base)} / ${esc(x.quote)}</option>`).join('');renderFavorites();await loadMarketChart()}catch(error){$('#chartStatus').textContent=error.message}}
async function loadMarketChart(){const symbol=$('#chartSymbol').value.trim().toUpperCase(),interval=$('#chartInterval').value,status=$('#chartStatus');$('#chartSymbol').value=symbol;status.textContent='Carregando candles…';try{const response=await fetch(`/api/market/klines?symbol=${encodeURIComponent(symbol)}&interval=${interval}`),data=await response.json();if(!response.ok)throw new Error(data.error);drawMarketChart(data.candles);const first=data.candles[0]?.close||0,last=data.candles.at(-1)?.close||0,change=first?(last-first)/first*100:0;$('#openedSymbol').textContent=symbol;$('#openedInterval').textContent=$('#chartInterval').selectedOptions[0].textContent;$('#openedPrice').textContent=number(last,8);$('#openedChange').textContent=`${change>=0?'+':''}${number(change)}%`;$('#openedChange').className=change>=0?'positive':'negative';status.textContent=`${data.candles.length} candles carregados. Último fechamento: ${number(last,8)}.`}catch(error){status.textContent=error.message}}
function drawMarketChart(candles){const c=$('#marketChart'),ctx=c.getContext('2d'),closes=candles.map(x=>x.close),min=Math.min(...closes),max=Math.max(...closes),range=max-min||1,pad=30,pts=closes.map((v,i)=>[pad+i*(c.width-pad*2)/(closes.length-1),(c.height-pad)-(v-min)/range*(c.height-pad*2)]);ctx.clearRect(0,0,c.width,c.height);ctx.strokeStyle='#dce5df';ctx.beginPath();for(let i=0;i<5;i++){const y=pad+i*(c.height-pad*2)/4;ctx.moveTo(pad,y);ctx.lineTo(c.width-pad,y)}ctx.stroke();ctx.strokeStyle=closes.at(-1)>=closes[0]?'#0b7a53':'#d94b4b';ctx.lineWidth=3;ctx.beginPath();pts.forEach((p,i)=>i?ctx.lineTo(...p):ctx.moveTo(...p));ctx.stroke()}
