async function loadPretrade(){const symbol=$('#chartSymbol').value.trim().toUpperCase(),button=$('#loadPretrade');button.disabled=true;button.textContent='Calculando…';try{const response=await fetch(`/api/market/pretrade?symbol=${encodeURIComponent(symbol)}`),data=await response.json();if(!response.ok)throw new Error(data.error);latestPretrade=data;const riskClass=data.risk.score>=65?'danger':data.risk.score>=35?'warning':'safe';$('#pretradeVerdict').className=`decision-banner ${riskClass}`;$('#pretradeVerdict').innerHTML=`<b>${esc(data.risk.label)} · ${number(data.risk.score,0)}/100</b><span>${data.rangePosition>=90?'Entrada perto da máxima diária. Espere confirmação ou planeje um stop pequeno.':'Dados carregados; defina stop e alvo antes de decidir.'}</span>`;$('#pretradeWarnings').innerHTML=(data.warnings||[]).map(message=>`<div class="alert warning"><b>ATENÇÃO</b><span>${esc(message)}</span></div>`).join('')||'<div class="alert info"><b>SEM ALERTA EXTREMO</b><span>Ainda assim defina stop e perda máxima.</span></div>';const access=data.marketAccess,book=data.orderBook;$('#pretradeDay').innerHTML=`<article><small>PREÇO</small><b>${number(data.price,8)}</b></article><article><small>MÍNIMA / MÁXIMA 24H</small><b>${number(data.low,8)} → ${number(data.high,8)}</b></article><article><small>VARIAÇÃO / AMPLITUDE</small><b class="${data.change24h>=0?'positive':'negative'}">${data.change24h>=0?'+':''}${number(data.change24h)}% · ${number(data.amplitude)}%</b></article><article><small>POSIÇÃO NO DIA</small><b>${number(data.rangePosition,0)}% ${data.rangePosition>=90?'⚠ TOPO':''}</b></article><article><small>SPREAD</small><b>${number(book.spreadPct,4)}%</b><span>${book.spreadPct<.08?'Bom':book.spreadPct<.2?'Atenção':'Alto'}</span></article><article><small>LIVRO ±0,5%</small><b>${book.imbalancePct>=0?'+':''}${number(book.imbalancePct)}%</b><span>${book.imbalancePct>=0?'Mais bids':'Mais asks'} · fotografia momentânea</span></article><article><small>ONDE OPERAR</small><b>${access.spot?'Spot ✓':'Spot —'} · ${access.crossMargin?'Cross 5x ✓':'Cross —'} · ${access.isolatedMargin?'Isolada 10x ✓':'Isolada —'}</b></article><article><small>ALINHAMENTO</small><b>${esc(data.alignment)}</b></article>`;$('#pretradeFrames').innerHTML=data.frames.map(f=>`<article><span class="tag">${esc(f.label)}</span><h3>${esc(f.trend)}</h3><p>Candle: ${f.change>=0?'+':''}${number(f.change)}%</p><p>ATR: ${number(f.atrPct)}%</p><p>RSI: ${number(f.rsi,0)} ${f.rsi>=75?'⚠':''}</p><p>Volume: ${number(f.volumeRatio)}x</p><small>EMA20 ${number(f.ema20,8)} · EMA50 ${number(f.ema50,8)}</small></article>`).join('');$('#planEntry').value=data.price;const atr=data.frames[1].atr;$('#planStop').value=Math.max(data.price-atr,0).toPrecision(8);$('#planTarget').value=(data.price+atr*2).toPrecision(8);$('#planLeverage').value=String(access.maxLeverage);calculateTradePlan()}catch(error){$('#pretradeDay').innerHTML=`<div class="empty negative">${esc(error.message)}</div>`}finally{button.disabled=false;button.textContent='Analisar agora'}}
function calculateTradePlan(){const capital=Number($('#planCapital').value),riskPct=Number($('#planRisk').value),entry=Number($('#planEntry').value),stop=Number($('#planStop').value),target=Number($('#planTarget').value),leverage=Number($('#planLeverage').value),result=$('#planResult');if(![capital,riskPct,entry,stop,target,leverage].every(Number.isFinite)||capital<=0||riskPct<=0||entry<=0||stop<=0||target<=0||stop===entry)return result.innerHTML='<div class="empty negative">Preencha capital, entrada, stop e alvo válidos.</div>';const direction=target>entry?'LONG':'SHORT',stopCorrect=direction==='LONG'?stop<entry:stop>entry,targetCorrect=direction==='LONG'?target>entry:target<entry;if(!stopCorrect||!targetCorrect)return result.innerHTML='<div class="empty negative">Para LONG: stop abaixo e alvo acima. Para SHORT: stop acima e alvo abaixo.</div>';const stopMove=Math.abs(entry-stop)/entry,riskMoney=capital*riskPct/100,quantity=riskMoney/Math.abs(entry-stop),notional=quantity*entry,margin=notional/leverage,targetMove=Math.abs(target-entry)/entry,reward=quantity*Math.abs(target-entry),rr=reward/riskMoney,exposurePct=notional/capital*100,leverageWarning=leverage>1?`Com ${leverage}x, juros, slippage e liquidação aumentam o risco. A perda no stop continua ${number(riskMoney,2)} USDT apenas se ele executar perto do preço.`:'Sem empréstimo de margem.';result.innerHTML=`<article><small>DIREÇÃO</small><b>${direction}</b></article><article><small>QUANTIDADE</small><b>${number(quantity,8)}</b></article><article><small>POSIÇÃO / MARGEM</small><b>${number(notional,2)} / ${number(margin,2)} USDT</b><span>Exposição ${number(exposurePct,0)}% do capital</span></article><article><small>PERDA NO STOP</small><b class="negative">-${number(riskMoney,2)} USDT</b><span>Movimento ${number(stopMove*100)}%</span></article><article><small>GANHO NO ALVO</small><b class="positive">+${number(reward,2)} USDT</b><span>Movimento ${number(targetMove*100)}%</span></article><article><small>RISCO : RETORNO</small><b class="${rr>=2?'positive':'negative'}">1 : ${number(rr,2)}</b><span>${rr>=2?'Plano ≥ 2R':'Alvo menor que 2R'}</span></article><p class="planner-warning">${leverageWarning}</p>`}
const strategyPanel=document.createElement('article');strategyPanel.className='panel strategy-panel';strategyPanel.innerHTML='<div class="panel-head"><div><small>ESTRATÉGIA PADRÃO</small><h3>Pullback confirmado · alvo mínimo 2R</h3></div><span class="tag">SEM ORDEM AUTOMÁTICA</span></div><div id="strategyBody" class="empty">Analise a moeda para verificar se existe setup.</div>';pretrade.before(strategyPanel);
function renderStrategy(data){if(!data?.strategy)return;const s=data.strategy,body=$('#strategyBody'),tone=s.action==='ESPERAR'||s.action==='SEM SETUP'?'warning':'info';body.className=`strategy-body ${tone}`;body.innerHTML=`<div><small>RESPOSTA AGORA</small><strong>${esc(s.action)}</strong><p>${esc(s.reason)}</p></div><div><small>ZONA DE ENTRADA</small><strong>${s.entryZone?`${number(s.entryZone.from,8)} → ${number(s.entryZone.to,8)}`:'NÃO DEFINIDA'}</strong><p>Entrar somente após confirmação; tocar a zona não basta.</p></div><div><small>STOP / ALVO</small><strong>${s.stop?`${number(s.stop,8)} / ${number(s.target,8)}`:'AGUARDAR'}</strong><p>Risco máximo ${number(s.riskPct)}% · retorno mínimo 1:${s.minRiskReward}.</p></div>`;if(s.stop&&s.target){$('#planEntry').value=((s.entryZone.from+s.entryZone.to)/2).toPrecision(8);$('#planStop').value=s.stop.toPrecision(8);$('#planTarget').value=s.target.toPrecision(8);$('#planRisk').value=s.riskPct;calculateTradePlan()}}
