const expenseView=document.createElement('section');expenseView.id='expenses';expenseView.className='view';expenseView.innerHTML='<div class="section-head"><div><p class="eyebrow">LIVRO FINANCEIRO</p><h2>Gastos e resultado real</h2><p class="muted">Consumo não é prejuízo de trade. Transferência não é lucro.</p></div><button class="secondary" id="refreshLedger">Atualizar</button></div><div class="metrics"><article><small>GASTOS DO MÊS</small><strong id="ledgerExpenses">—</strong><span>Cartão e consumo</span></article><article><small>RESULTADO DE TRADES</small><strong id="ledgerTrades">—</strong><span>Lançamentos importados/manuais</span></article><article><small>TAXAS + JUROS</small><strong id="ledgerCosts">—</strong><span>Custos de operação</span></article><article><small>RECEITAS</small><strong id="ledgerIncome">—</strong><span>Fora de transferências</span></article></div><div class="grid-main"><form id="ledgerForm" class="panel form"><span class="tag">NOVO LANÇAMENTO</span><label>Tipo<select id="ledgerType"><option value="expense">Gasto/cartão</option><option value="trade_pnl">Resultado de trade</option><option value="fee">Taxa</option><option value="interest">Juros</option><option value="transfer">Transferência</option><option value="income">Receita</option></select></label><label>Descrição<input id="ledgerDescription" placeholder="Ex.: Hambúrguer" maxlength="160" required></label><label>Categoria<select id="ledgerCategory"><option>Alimentação</option><option>Transporte</option><option>Assinaturas</option><option>Compras</option><option>Trade</option><option>Taxas</option><option>Transferências</option><option>Outros</option></select></label><label>Valor em R$<input id="ledgerBrl" type="number" min="0" step="0.01" value="0"></label><label>Valor em USDT<input id="ledgerUsdt" type="number" min="0" step="any" value="0"></label><label>Data e hora<input id="ledgerDate" type="datetime-local" required></label><button class="primary" type="submit">Salvar lançamento</button><p id="ledgerResult" class="muted"></p></form><article class="panel table-wrap"><table><thead><tr><th>Data</th><th>Tipo</th><th>Descrição</th><th>Categoria</th><th>R$</th><th>USDT</th><th></th></tr></thead><tbody id="ledgerRows"></tbody></table><div id="ledgerEmpty" class="empty">Nenhum lançamento.</div></article></div>';
