async function loadLedger(){try{const response=await fetch('/api/ledger?limit=200'),data=await response.json();if(!response.ok)throw new Error(data.error);const s=data.summary||{};$('#ledgerExpenses').textContent=`R$ ${number(s.expenses_brl||0,2)}`;$('#ledgerTrades').textContent=`${number(s.trade_pnl_usdt||0,4)} USDT`;$('#ledgerCosts').textContent=`${number(s.costs_usdt||0,4)} USDT`;$('#ledgerIncome').textContent=`R$ ${number(s.income_brl||0,2)}`;$('#ledgerRows').innerHTML=(data.entries||[]).map(x=>`<tr><td>${new Date(x.occurred_at).toLocaleString('pt-BR')}</td><td>${esc(x.type)}</td><td>${esc(x.description)}</td><td>${esc(x.category)}</td><td>${number(x.amount_brl,2)}</td><td>${number(x.amount_usdt,4)}</td><td>${x.source==='manual'?`<button class="delete-ledger" data-id="${x.id}">Excluir</button>`:''}</td></tr>`).join('');$('#ledgerEmpty').style.display=data.entries?.length?'none':'block';$$('.delete-ledger').forEach(button=>button.onclick=async()=>{await fetch(`/api/ledger/${button.dataset.id}`,{method:'DELETE'});loadLedger()})}catch(error){$('#ledgerResult').textContent=error.message}}
$('#ledgerForm').onsubmit=async event=>{event.preventDefault();const payload={type:$('#ledgerType').value,description:$('#ledgerDescription').value,category:$('#ledgerCategory').value,amountBrl:Number($('#ledgerBrl').value),amountUsdt:Number($('#ledgerUsdt').value),occurredAt:new Date($('#ledgerDate').value).toISOString()};const response=await fetch('/api/ledger',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(payload)}),data=await response.json();if(!response.ok)return $('#ledgerResult').textContent=data.error;$('#ledgerResult').textContent='Lançamento salvo sem alterar o resultado de trades.';$('#ledgerDescription').value='';loadLedger()};$('#refreshLedger').onclick=loadLedger;
syncLedgerButton.onclick=async()=>{syncLedgerButton.disabled=true;syncLedgerButton.textContent='Sincronizando…';$('#ledgerResult').textContent='Consultando os últimos 89 dias na Binance Pay…';try{const response=await fetch('/api/ledger/sync-binance',{method:'POST'}),data=await response.json();if(!response.ok)throw new Error(data.error);$('#ledgerResult').textContent=`${data.imported} novos gastos importados; ${data.duplicates} já estavam salvos. ${data.warning}`;await loadLedger()}catch(error){$('#ledgerResult').textContent=`Não foi possível importar: ${error.message}. A chave precisa permitir leitura dos dados da conta.`}finally{syncLedgerButton.disabled=false;syncLedgerButton.textContent='Sincronizar gastos Binance'}};
