async function loadPro(){const button=$('#refreshPro');button.disabled=true;button.textContent='Atualizando…';try{const [marginResponse,setupResponse,planResponse,alertResponse]=await Promise.all([fetch('/api/margin/monitor'),fetch('/api/market/setups'),fetch('/api/trade-plans?limit=30'),fetch('/api/alerts?limit=30')]),margin=await marginResponse.json(),setups=await setupResponse.json(),plans=await planResponse.json(),alerts=await alertResponse.json();if(!marginResponse.ok)throw new Error(margin.error);$('#proMarginLevel').textContent=margin.level?number(margin.level,2):'—';$('#proMarginRisk').textContent=margin.level&&margin.level<1.5?'CRÍTICO — reduza dívida':margin.level&&margin.level<2?'ATENÇÃO':'Monitorado';$('#proDebt').textContent=`${number(margin.totalDebtUsdt,4)} USDT`;$('#proNet').textContent=`${number(margin.netUsdt,4)} USDT`;$('#proPositions').innerHTML=margin.positions.map(p=>`<tr><td><b>${esc(p.asset)}</b></td><td class="${p.direction==='SHORT'?'negative':'positive'}">${p.direction}</td><td>${number(p.net,8)}</td><td>${number(p.price,8)}</td><td>${number(p.netUsdt,4)}</td><td>${number(p.borrowed,8)}</td><td class="${p.interest>0?'negative':''}">${number(p.interest,8)}</td><td>${number(p.debtUsdt,4)}</td></tr>`).join('');$('#proPositionsEmpty').style.display=margin.positions.length?'none':'block';$('#proSetups').innerHTML=(setups.setups||[]).map(x=>`<tr><td><button class="link setup-symbol" data-symbol="${esc(x.symbol)}">${esc(x.symbol)}</button></td><td><span class="tag">${esc(x.setup)}</span></td><td>${number(x.price,8)}</td><td class="${x.change24h>=0?'positive':'negative'}">${x.change24h>=0?'+':''}${number(x.change24h)}%</td><td>${number(x.rsi15,0)}</td><td>${number(x.atr15Pct)}%</td><td>${number(x.volumeRatio15)}x</td><td>${esc(x.trend15||'—')}</td><td>${esc(x.trend1h||'—')}</td><td>${x.maxLeverage}x</td><td>${esc(x.reason)}</td></tr>`).join('');$$('.setup-symbol').forEach(link=>link.onclick=()=>{$('#chartSymbol').value=link.dataset.symbol;show('markets');loadMarketChart()});$('#proPlans').textContent=(plans.plans||[]).filter(x=>x.status==='PLANNED').length;$('#proPlanList').innerHTML=(plans.plans||[]).map(p=>`<div class="trade-row"><div><b>${esc(p.symbol)} · ${p.direction} · ${p.leverage}x</b><small>Entrada ${number(p.entry,8)} · Stop ${number(p.stop,8)} · Alvo ${number(p.target,8)} · 1:${number(p.risk_reward)}</small></div><span class="tag">${esc(p.status)}</span></div>`).join('')||'<div class="empty">Nenhum plano salvo.</div>';$('#proAlerts').innerHTML=(alerts.alerts||[]).map(a=>`<div class="alert ${a.level==='danger'?'warning':'info'}"><div><b>${esc(a.title)}</b><span>${esc(a.message)}</span><small>${new Date(a.created_at).toLocaleString('pt-BR')}</small></div></div>`).join('')||'<div class="empty">Nenhum alerta.</div>';$('#whatsappState').textContent=alerts.whatsappConfigured?'WhatsApp configurado para envio.':'WhatsApp ainda sem webhook: os alertas permanecem salvos nesta tela.'}catch(error){$('#proPositionsEmpty').textContent=error.message;$('#proPositionsEmpty').style.display='block'}finally{button.disabled=false;button.textContent='Atualizar tudo'}}
$('#refreshPro').onclick=loadPro;$('#evaluatePlans').onclick=async()=>{const button=$('#evaluatePlans');button.disabled=true;button.textContent='Avaliando…';try{await fetch('/api/trade-plans/evaluate',{method:'POST'});await loadPro()}finally{button.disabled=false;button.textContent='Avaliar planos'}};
